# What if the output should preserve cells that are unique in their row/col?
# Or cells that are different from the majority of their quadrant?

def find_unique_in_quadrant(puzzle, r, c):
    """Check if cell is unique in its 2x2 quadrant"""
    if r <= 1 and c <= 1:
        quadrant = [puzzle[0][0], puzzle[0][1], puzzle[1][0], puzzle[1][1]]
    elif r <= 1 and c >= 3:
        quadrant = [puzzle[0][3], puzzle[0][4], puzzle[1][3], puzzle[1][4]]
    elif r >= 3 and c <= 1:
        quadrant = [puzzle[3][0], puzzle[3][1], puzzle[4][0], puzzle[4][1]]
    elif r >= 3 and c >= 3:
        quadrant = [puzzle[3][3], puzzle[3][4], puzzle[4][3], puzzle[4][4]]
    elif r >= 6 and c <= 1:
        quadrant = [puzzle[6][0], puzzle[6][1], puzzle[7][0], puzzle[7][1]]
    elif r >= 6 and c >= 3:
        quadrant = [puzzle[6][3], puzzle[6][4], puzzle[7][3], puzzle[7][4]]
    else:
        return puzzle[r][c]  # cross

    counter = {}
    for v in quadrant:
        counter[v] = counter.get(v, 0) + 1

    if counter.get(puzzle[r][c], 0) == 1:
        return puzzle[r][c]  # unique = 1, else 2
    return 2  # majority

